e":"D15 p. 1","options":[{"id":"experienced","text":"Déjà fait"},{"id":"never","text":"Jamais"}]},"cv":"final-2026-10-24"},{"bank":"conv_never","idx":50,"value":{"id":"C3-03-051","text":"Je n’ai jamais eu un fou rire en voyant la tête de l’autre pendant.","adult":false,"source":"D15 p. 1","options":[{"id":"experienced","text":"Déjà fait"},{"id":"never","text":"Jamais"}]},"cv":"final-2026-10-24"},{"bank":"conv_never","idx":51,"value":{"id":"C3-03-052","text":"Je n’ai jamais inventé une excuse pour aller aux toilettes en plein milieu.","adult":true,"source":"D15 p. 1","options":[{"id":"experienced","text":"Déjà fait"},{"id":"never","text":"Jamais"}]},"cv":"final-2026-10-24"},{"bank":"conv_never","idx":52,"value":{"id":"C3-03-053","text":"Je n’ai jamais eu un orgasme et fait semblant que non.","adult":true,"source":"D15 p. 1","options":[{"id":"experienced","text":"Déjà fait"},{"id":"never","text":"Jamais"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":0,"value":{"id":"PK-G10-001","text":"Parler de sexe avant de faire l’amour, c’est important.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":1,"value":{"id":"PK-G10-002","text":"Un fantasme peut rester dans la tête sans jamais être réalisé.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":2,"value":{"id":"PK-G10-003","text":"Dire non après avoir dit oui, c’est normal.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":3,"value":{"id":"PK-G10-004","text":"Les sextoys peuvent améliorer la vie sexuelle d’un couple.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":4,"value":{"id":"PK-G10-005","text":"Tout le monde n’a pas besoin d’avoir un orgasme à chaque rapport.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":5,"value":{"id":"PK-G10-006","text":"La masturbation en couple, ça peut être un sujet à discuter.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":6,"value":{"id":"PK-G10-007","text":"Demander un dépistage, ce n’est pas un manque de confiance.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":7,"value":{"id":"PK-G10-008","text":"Le dirty talk, ça peut être très excitant.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":8,"value":{"id":"PK-G10-009","text":"Un moment intime peut être génial même sans pénétration.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":9,"value":{"id":"PK-G10-010","text":"Il est normal que les envies ne soient pas toujours synchronisées.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":10,"value":{"id":"PK-G10-011","text":"Un aftercare, c’est aussi important que le moment lui-même.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":11,"value":{"id":"PK-G10-012","text":"On peut aimer quelque chose en théorie sans avoir envie de le tester.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":12,"value":{"id":"PK-G10-013","text":"Parler de ses limites, ça rend les rapports plus sereins.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":13,"value":{"id":"PK-G10-014","text":"Un sextoy n’est pas un jugement sur le partenaire.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":14,"value":{"id":"PK-G10-015","text":"Le consentement peut être retiré à tout moment.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":15,"value":{"id":"PK-G10-016","text":"Faire l’amour ailleurs que dans une chambre, ça peut être fun.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":16,"value":{"id":"PK-G10-017","text":"Les compliments pendant un moment intime, ça change tout.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":17,"value":{"id":"PK-G10-018","text":"Un fou rire au lit, ça peut arriver et c’est pas grave.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":18,"value":{"id":"PK-G10-019","text":"On n’est pas obligé de tout essayer.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":19,"value":{"id":"PK-G10-020","text":"Un message hot peut être très excitant.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":20,"value":{"id":"PK-G10-021","text":"La lumière allumée pendant un rapport, ça peut être gênant ou excitant selon les personnes.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":21,"value":{"id":"PK-G10-022","text":"Un rapport peut être bon même s’il est court.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":22,"value":{"id":"PK-G10-023","text":"Demander ce que l’autre aime, c’est sexy.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":23,"value":{"id":"PK-G10-024","text":"Un fantasme partagé ne veut pas dire qu’on doit le réaliser.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":24,"value":{"id":"PK-G10-025","text":"Le silence pendant un moment intime peut être très intense.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":25,"value":{"id":"PK-G10-026","text":"On peut changer d’avis en cours de route.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":26,"value":{"id":"PK-G10-027","text":"Un sextoy trop bruyant peut casser l’ambiance.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":27,"value":{"id":"PK-G10-028","text":"Parler de ses envies par message, c’est parfois plus facile.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":28,"value":{"id":"PK-G10-029","text":"Un moment improvisé peut être meilleur qu’un moment prévu.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_opinion","idx":29,"value":{"id":"PK-G10-030","text":"Le plus important, c’est que les deux personnes soient à l’aise.","adult":true,"source":"Packs G05, G08, G09, G10 (PDF)","options":[{"id":"agree","text":"D’accord"},{"id":"disagree","text":"Pas d’accord"}]},"cv":"final-2026-10-24"},{"bank":"conv_predict","idx":0,"value":{"id":"PK-G05-001","text":"Tu dirais que je suis plutôt du matin ou du soir ?","adult":false,"source":"Packs G05, G08, G09, G10 (PDF)"},"cv":"final-2026-10-24"},{"bank":"conv_predict","idx":1,"value":{"id":"PK-G05-002","text":"D’après toi, quel parfum de glace je préfère ?","adult":false,"source":"Packs G05, G08, 