i-jeux interactifs 24 entrées uniques dans 1 sous-catégories. Les PDF du dossier ne contiennent de consignes textuelles de mini-jeux que pour « Cite trois en 10 secondes ». Les autres mini-jeux et les banques absentes sont recensés à la fin de cette catégorie.","Aucun score, aucune bonne réponse, aucune compatibilité.","Source : catalogue éditorial consolidé Noodeu du 24/10/2026 (Le pire scénario - complément adulte, Si on était des personnages - complément adulte, Le défi absurde - complément adulte)."],"privacy":"Ta réponse reste privée. Tu choisis ensuite de la partager, de la garder pour toi ou de passer ; rien n'est révélé avant que vous ayez terminé tous les deux, et tu peux retirer un partage.","objective":"Scénarios, personnages et défis absurdes","step_texts":{}}},{"id":"ND-Q-RND1","config":{"bank":null,"engine":"board","mechanic":"pack_conversation","rounds":20,"score":"none","turn":"simultaneous","settings":{"questions":{"label":"Nombre de questions","default":10,"options":[5,10,20]}},"pack":{"code":"RND1","content_version":"final-2026-10-24","count":20,"editorial_release":"final-2026-10-24","instrument":"ALEATOIRE","response":"open","scales":{},"set_size":null,"random":true,"pool":["q_gottman_open","q_usu_roadtrip","q_series","q_complicite","q_recul","q_emotions","q_reconfort"]}},"rules":{"how_to":["Choisissez le nombre de questions dans le salon : 5, 10 ou 20.","Les questions sont tirées au hasard parmi les questions libres de la rubrique, selon vos réglages d'intensité et de +18.","Chacun répond en privé, puis choisit de partager, de garder pour soi ou de passer ; rien n'est révélé avant que vous ayez terminé tous les deux."],"details":["Les questionnaires structurés (36 questions, tests) gardent leur ordre et ne sont jamais mélangés ici.","Aucun score, aucune bonne réponse, aucune compatibilité."],"privacy":"Ta réponse reste privée. Tu choisis ensuite de la partager, de la garder pour toi ou de passer ; rien n'est révélé avant que vous ayez terminé tous les deux, et tu peux retirer un partage.","objective":"Questionnaire aléatoire","step_texts":{}}},{"id":"ND-Q-RND2","config":{"bank":null,"engine":"board","mechanic":"pack_conversation","rounds":20,"score":"none","turn":"simultaneous","settings":{"questions":{"label":"Nombre de questions","default":10,"options":[5,10,20]}},"pack":{"code":"RND2","content_version":"final-2026-10-24","count":20,"editorial_release":"final-2026-10-24","instrument":"ALEATOIRE","response":"open","scales":{},"set_size":null,"random":true,"pool":["q_hc_envies","q_hc_parler","q_hc_corps","q_hc_protection","q_hc_plaisir","q_hc_envies_plus","q_hc_intimite_plus","q_hc_complements"]}},"rules":{"how_to":["Choisissez le nombre de questions dans le salon : 5, 10 ou 20.","Les questions sont tirées au hasard parmi les questions libres de la rubrique, selon vos réglages d'intensité et de +18.","Chacun répond en privé, puis choisit de partager, de garder pour soi ou de passer ; rien n'est révélé avant que vous ayez terminé tous les deux."],"details":["Les questionnaires structurés (36 questions, tests) gardent leur ordre et ne sont jamais mélangés ici.","Aucun score, aucune bonne réponse, aucune compatibilité."],"privacy":"Ta réponse reste privée. Tu choisis ensuite de la partager, de la garder pour toi ou de passer ; rien n'est révélé avant que vous ayez terminé tous les deux, et tu peux retirer un partage.","objective":"Questionnaire aléatoire À huis clos","step_texts":{}}}]$n$::jsonb)
  as x(id text, config jsonb, rules jsonb)),
changed as (
  select s.* from src s join public.games g on g.id = s.id
  where not exists (select 1 from public.game_versions v where v.game_id = s.id and v.version = g.current_version
                    and v.rules = s.rules and v.config = s.config)),
ins as (
  insert into public.game_versions (game_id, version, rules, config, published_at)
  select c.id, coalesce((select max(version) from public.game_versions where game_id = c.id), 0) + 1, c.rules, c.config, now()
  from changed c returning game_id, version)
update public.games g set current_version = ins.version from ins where g.id = ins.game_id;

-- Données personnelles qui visaient une question disparue, et progression des packs réécrits.
delete from public.later_items l where not exists (select 1 from public.content_banks cb where cb.bank = l.bank and cb.value ->> 'id' = l.item_id);
delete from public.item_favorites f where f.kind = 'question'
  and not exists (select 1 from public.content_banks cb where cb.bank = f.bank and cb.value ->> 'id' = f.item_id);
delete from public.item_feedback f where not exists (select 1 from public.content_banks cb where cb.bank = f.bank and cb.value ->> 'id' = f.item_id);
delete from public.daily_cards dc where not exists (select 1 from public.content_banks cb where cb.bank = dc.bank and cb.value ->> 'id' = dc.item_id);
delete from public.content_meta m where not exists (select 1 from public.content_banks cb where cb.bank = m.bank and cb.value ->> 'id' = m.item_id);
delete from private.pack_progress where game_id in ('ND-Q-P01', 'ND-Q-P11', 'ND-Q-P12', 'ND-Q-P13', 'ND-Q-P14', 'ND-Q-P03', 'ND-Q-P15');

